    12	/// Completion fraction shared by `ProgressBuilder::build` and
    13	/// `ProgressTracker::get_percentage`.
    14	///
    15	/// Divide first in `f32`, then let `Format::percentage` multiply by 100 — this is
    16	/// the order the reference binary uses, and it is float-only, so `total == 0`
    17	/// yields inf/NaN instead of panicking (an integer `progress * 100 / total`
    18	/// would panic in Rust).
    19	pub(crate) fn ratio(progress: i32, total: i32) -> f32 {
    20	    progress as f32 / total as f32
