     1	//! Port of the C++ `indicators::Format` static-member helper.
     2	
     3	/// The C++ default argument on `percentage(float value, int precision = 1)`.
     4	pub const DEFAULT_PRECISION: usize = 1;
     5	
     6	/// Stateless holder for the formatting helpers, mirroring the C++ class that
     7	/// only ever exposes static members.
     8	pub struct Format;
     9	
    10	impl Format {
    11	    /// C++ `Format::percentage(value)` — the call form that takes the default
    12	    /// `precision = 1`. Line 4 of the expected output ("33.0%") uses it.
    13	    pub fn percentage(value: f32) -> String {
    14	        Self::percentage_with_precision(value, DEFAULT_PRECISION)
    15	    }
    16	
    17	    /// C++ `Format::percentage(value, precision)`:
    18	    /// `oss << std::fixed << std::setprecision(precision) << (value * 100.0f) << "%"`.
    19	    ///
    20	    /// The multiply happens in `f32` (the product is rounded back to `f32`) and is
    21	    /// then widened to `f64` for rendering, mirroring the `mulss` + `cvtss2sd`
    22	    /// pipeline of an `ostream << float` insertion. Rust's `{:.N$}` is the exact
    23	    /// equivalent of `std::fixed` + `setprecision(N)`: exactly N fractional digits,
    24	    /// never scientific notation, trailing zeros preserved, round-half-to-even on
    25	    /// the exact binary value.
    26	    pub fn percentage_with_precision(value: f32, precision: usize) -> String {
    27	        let scaled = f64::from(value * 100.0f32);
    28	        format!("{scaled:.precision$}%")
    29	    }
    30	}
