     1	use super::{ratio, Format};
     2	
     3	/// Port of C++ `indicators::ProgressTracker`.
     4	#[derive(Debug, Clone)]
     5	pub struct ProgressTracker {
     6	    progress: i32,
     7	    total: i32,
     8	    stages: Vec<String>,
     9	}
    10	
    11	impl ProgressTracker {
    12	    /// C++ `indicators::ProgressTracker tracker;`
    13	    pub fn new() -> Self {
    14	        Self { progress: 0, total: 100, stages: Vec::new() }
    15	    }
    16	
    17	    /// Chainable, mirroring
    18	    /// `tracker.add_stage("Downloading").add_stage("Processing").add_stage("Saving");`.
    19	    pub fn add_stage(&mut self, name: &str) -> &mut Self {
    20	        self.stages.push(name.to_string());
    21	        self
    22	    }
    23	
    24	    /// Called as a standalone statement in test5.cpp, so it mirrors C++ `void`.
    25	    pub fn set_progress(&mut self, value: i32) {
    26	        self.progress = value;
    27	    }
    28	
    29	    /// Called as a standalone statement in test5.cpp, so it mirrors C++ `void`.
    30	    pub fn set_total(&mut self, value: i32) {
    31	        self.total = value;
    32	    }
    33	
    34	    /// The stages are recorded and never read back — the C++ program stores three
    35	    /// of them and prints none. This accessor is the only reader of the field, and
    36	    /// nothing in a binary crate can reach it, so rustc reports it as dead code;
    37	    /// the allow is scoped to this one item rather than muting the whole crate.
    38	    #[allow(dead_code)]
    39	    pub fn stages(&self) -> &[String] {
    40	        &self.stages
    41	    }
    42	
    43	    /// `"{progress}/{total}"`, e.g. `{1, 3}` -> `"1/3"`.
    44	    pub fn get_progress(&self) -> String {
    45	        format!("{}/{}", self.progress, self.total)
    46	    }
    47	
    48	    /// Renders the completion percentage, e.g. `{1, 3}` -> `"33.3%"`.
    49	    pub fn get_percentage(&self) -> String {
    50	        Format::percentage(ratio(self.progress, self.total))
    51	    }
    52	}
    53	
    54	impl Default for ProgressTracker {
    55	    fn default() -> Self {
    56	        Self::new()
    57	    }
    58	}
